mapper.select:
SELECT
COUNT(*) AS total
FROM
ask_questions aq



            AND (
                aq.class_id IS NULL
                OR EXISTS (
                    SELECT 1 FROM user_class uc3
                    WHERE uc3.class_id = aq.class_id AND uc3.user_id = #{userId}
                )
            )



        AND aq.content LIKE CONCAT('%', #{content}, '%')


        AND aq.recipient = #{recipient}

SELECT u1.user_name AS senderName, u2.user_name AS recipientName, cr.resource_name AS topic, c.class_name AS className, co.course_name AS courseName,
FROM ask_questions aq LEFT JOIN `user` u1 ON u1.id = aq.sender LEFT JOIN `user` u2 ON u2.id = aq.recipient LEFT JOIN course_resource cr ON cr.id = aq.resource_id LEFT JOIN class c ON c.id = aq.class_id LEFT JOIN course co ON co.id = c.course_id
AND ( aq.class_id IS NULL OR EXISTS ( SELECT 1 FROM user_class uc3 WHERE uc3.class_id = aq.class_id AND uc3.user_id = #{userId} ) )
AND aq.content LIKE CONCAT('%', #{content}, '%')
AND aq.recipient = #{recipient}
ORDER BY aq.id DESC LIMIT #{page},#{pageSize}
